export const code = async (inputs) => {
  const symbols = [
    { id: 'S&P 500 (USA)', ticker: '^GSPC' },
    { id: 'Nasdaq Composite', ticker: '^IXIC' },
    { id: 'Dow Jones', ticker: '^DJI' },
    { id: 'OMX Helsinki 25', ticker: '^OMXH25' },
    { id: 'OMX Stockholm 30', ticker: '^OMX' },
    { id: 'STOXX Europe 600', ticker: '^STOXX' },
    { id: 'DAX (Saksa)', ticker: '^GDAXI' },
    { id: 'FTSE 100 (UK)', ticker: '^FTSE' },
    { id: 'US 10Y Treasury Yield', ticker: '^TNX' },
    { id: 'Brent Crude Oil', ticker: 'BZ=F' },
    { id: 'WTI Crude Oil', ticker: 'CL=F' },
    { id: 'Gold Futures', ticker: 'GC=F' },
    { id: 'EUR/USD', ticker: 'EURUSD=X' },
    { id: 'EUR/SEK', ticker: 'EURSEK=X' },
    { id: 'USD/JPY', ticker: 'USDJPY=X' },
    { id: 'Bitcoin USD', ticker: 'BTC-USD' },
    { id: 'Nokia (Helsinki)', ticker: 'NOKIA.HE' },
    { id: 'Nordea (Helsinki)', ticker: 'NDA-FI.HE' },
    { id: 'Kone (Helsinki)', ticker: 'KNEBV.HE' },
    { id: 'UPM-Kymmene (Helsinki)', ticker: 'UPM.HE' },
    { id: 'Neste (Helsinki)', ticker: 'NESTE.HE' },
    { id: 'Sampo (Helsinki)', ticker: 'SAMPO.HE' },
    { id: 'Fortum (Helsinki)', ticker: 'FORTUM.HE' },
    { id: 'Wärtsilä (Helsinki)', ticker: 'WRT1V.HE' },
    { id: 'Stora Enso (Helsinki)', ticker: 'STERV.HE' },
    { id: 'Metso (Helsinki)', ticker: 'METSO.HE' },
    { id: 'Kesko (Helsinki)', ticker: 'KESKOB.HE' },
    { id: 'Orion (Helsinki)', ticker: 'ORNBV.HE' },
    { id: 'Valmet (Helsinki)', ticker: 'VALMT.HE' },
    { id: 'Outokumpu (Helsinki)', ticker: 'OUT1V.HE' },
    { id: 'Kalmar (Helsinki)', ticker: 'KALMAR.HE' },
    { id: 'Mandatum (Helsinki)', ticker: 'MANTA.HE' },
    { id: 'Elisa (Helsinki)', ticker: 'ELISA.HE' },
    { id: 'Tietoevry (Helsinki)', ticker: 'TIETO.HE' },
    { id: 'Konecranes (Helsinki)', ticker: 'KCR.HE' },
    { id: 'Nokian Renkaat (Helsinki)', ticker: 'TYRES.HE' },
    { id: 'Finnair (Helsinki)', ticker: 'FIA1S.HE' },
    { id: 'Metsä Board (Helsinki)', ticker: 'METSB.HE' },
    { id: 'Qt Group (Helsinki)', ticker: 'QTCOM.HE' },
    { id: 'Kemira (Helsinki)', ticker: 'KEMIRA.HE' },
    { id: 'Huhtamäki (Helsinki)', ticker: 'HUH1V.HE' },
    { id: 'Sanoma (Helsinki)', ticker: 'SANOMA.HE' },
    { id: 'Fiskars (Helsinki)', ticker: 'FSKRS.HE' }
  ];

  const results = [];
  const host = ['query2', 'finance', 'yahoo', 'com'].join('.');
  const baseUrl = 'https://' + host + '/v8/finance/chart/';
  const webHost = ['finance', 'yahoo', 'com'].join('.');
  const nowSec = Math.floor(Date.now() / 1000);
  const helsDate = function (ts) {
    try {
      return new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Helsinki', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(ts * 1000));
    } catch (e) {
      return new Date((ts + 7200) * 1000).toISOString().slice(0, 10);
    }
  };
  const todayHel = helsDate(nowSec);

  for (const item of symbols) {
    const quoteUrl = 'https://' + webHost + '/quote/' + encodeURIComponent(item.ticker) + '/';
    try {
      const url = baseUrl + encodeURIComponent(item.ticker) + '?interval=1d&range=5d';
      const res = await fetch(url, {
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        }
      });
      const data = await res.json();
      const resultList = data.chart.result;
      const meta = resultList.at(0).meta;
      const price = meta.regularMarketPrice;
      const closes = ((resultList.at(0).indicators.quote.at(0).close) || []).filter((v) => v !== null && v !== undefined);
      let changePct = '0.00';
      if (typeof meta.regularMarketChangePercent === 'number') {
        changePct = meta.regularMarketChangePercent.toFixed(2);
      } else {
        const prevClose = meta.previousClose || (closes.length >= 2 ? closes.at(closes.length - 2) : meta.chartPreviousClose);
        changePct = prevClose ? (((price - prevClose) / prevClose) * 100).toFixed(2) : '0.00';
      }
      const sign = Number(changePct) > 0 ? '+' : '';

      const cp = meta.currentTradingPeriod && meta.currentTradingPeriod.regular;
      const stamps = resultList.at(0).timestamp || [];
      const rawCloses = (resultList.at(0).indicators.quote.at(0).close) || [];
      let barTs = 0;
      for (let k = 0; k < stamps.length; k++) {
        if (rawCloses[k] !== null && rawCloses[k] !== undefined) { barTs = stamps[k]; }
      }
      const lastDate = barTs ? helsDate(barTs) : 'tuntematon';
      const tradedToday = barTs ? (lastDate === todayHel) : false;
      const inSession = cp ? (!(nowSec < cp.start) && nowSec < cp.end) : false;
      let status;
      if (!barTs) {
        status = 'TILA TUNTEMATON';
      } else if (tradedToday) {
        status = inSession ? 'AUKI PARHAILLAAN (kauppaa k\u00e4yty t\u00e4n\u00e4\u00e4n)' : 'SULKEUTUNUT T\u00c4N\u00c4\u00c4N (t\u00e4m\u00e4n p\u00e4iv\u00e4n p\u00e4\u00e4t\u00f6skurssi)';
      } else if (cp && nowSec < cp.start && helsDate(cp.start) === todayHel) {
        status = `EI VIEL\u00c4 AVANNUT (luku ja muutos ovat edelt\u00e4v\u00e4lt\u00e4 kauppap\u00e4iv\u00e4lt\u00e4 ${lastDate})`;
      } else if (inSession && nowSec - cp.start < 1800) {
        status = `AVAUTUMASSA (t\u00e4m\u00e4n p\u00e4iv\u00e4n kurssia ei viel\u00e4 ole, luku ja muutos ovat p\u00e4iv\u00e4lt\u00e4 ${lastDate})`;
      } else {
        status = `SULJETTU, EI KAUPANK\u00c4YNTI\u00c4 T\u00c4N\u00c4\u00c4N (vapaap\u00e4iv\u00e4 tai viikonloppu, luku ja muutos ovat viimeisimm\u00e4lt\u00e4 kauppap\u00e4iv\u00e4lt\u00e4 ${lastDate})`;
      }

      results.push(`${item.id}: ${price} (${sign}${changePct}%) [${status}] | Linkki: ${quoteUrl}`);
    } catch (e) {
      results.push(`${item.id}: ei saatavilla | Linkki: ${quoteUrl}`);
    }
  }

  return { marketData: results.join('\n') };
};

